#!/bin/sh
# Installed image lookup + QEMU launch for the Awai Desktop macOS app.
# This is the .app bundle executable (generated by assemble-app.sh).
#
# Resolution order for the disk image:
#   1. OTEHON_IMAGE env (explicit override, e.g. a test copy)
#   2. Contents/Resources/otehon-desktop.qcow2 (bundled with --bundle-image)
#   3. ~/Library/Application Support/Otehon/otehon-desktop-<version>.qcow2
#      (installed by install-image.sh)
#
# Display honours OTEHON_DISPLAY (default cocoa; "none" runs headless).
# Flags mirror nixos/otehon/run-desktop-qemu.sh, which stays the contract
# for the guest side (machine, accel, drives, usb input, no network).
set -u
here=$(cd "$(dirname "$0")" && pwd)
version="__VERSION__"
firmware=${OTEHON_EDK2:-/opt/homebrew/share/qemu/edk2-aarch64-code.fd}

image=${OTEHON_IMAGE:-}
if [ -z "$image" ] && [ -f "$here/../Resources/otehon-desktop.qcow2" ]; then
  image="$here/../Resources/otehon-desktop.qcow2"
fi
if [ -z "$image" ]; then
  image="$HOME/Library/Application Support/Otehon/otehon-desktop-$version.qcow2"
fi

err() {
  echo "Awai Desktop: $1" >&2
  # A double-clicked launch has no stderr worth reading, so also raise a GUI
  # alert — but never block a headless run on it: bounded by alarm, detached.
  if [ ! -t 2 ] && command -v osascript >/dev/null && command -v perl >/dev/null; then
    perl -e 'alarm 4; exec @ARGV' osascript \
      -e "display alert \"Awai Desktop\" message \"$1\" as critical" >/dev/null 2>&1 &
  fi
  exit 3
}

[ -f "$image" ] || err "No disk image: $image. Run install-image.sh first."
command -v qemu-system-aarch64 >/dev/null || err "no qemu-system-aarch64 (brew install qemu)"
[ -f "$firmware" ] || err "no firmware: $firmware"

exec qemu-system-aarch64 \
  -machine virt,accel=hvf -cpu host -smp "${OTEHON_VM_CPUS:-4}" -m "${OTEHON_VM_MEMORY:-4096}" \
  -bios "$firmware" \
  -drive "if=virtio,format=qcow2,file=$image" \
  -device virtio-gpu-pci,xres=1440,yres=900 \
  -device qemu-xhci -device usb-kbd -device usb-tablet \
  -nic "${OTEHON_NET:-user}" -display "${OTEHON_DISPLAY:-cocoa}" ${OTEHON_QEMU_EXTRA:-}
